"""Package Aqua v11 / Test 3, main finisher411 and neutral-air dodge504."""
from pathlib import Path
import csv,hashlib,json,shutil,sys,zipfile,struct
from aqua_v11_plan import SETS,BANK
ROOT=Path(__file__).resolve().parents[1]
DEST=ROOT/'KH1FM_Aqua_Animation_Test_v11'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()

README="KH1FM AQUA ANIMATION TEST v11 - TEST 3\nSteam Global / OpenKH Panacea\n\nNEW MAIN AQUA ACTIONS\n- Ground combo finisher: 411 (first/second ground attacks stay 300/301/302).\n- Neutral aerial dodge: 504. In free air, release Jump/Circle after takeoff,\n  leave the left stick neutral, then press Circle again. One use per airtime;\n  land to rearm. The numbered Aqua entries inherit this movement action.\n- Normal falling remains 506. Fire316/391, Thunder317/390, Cure318/427 and\n  LEFT-hand spell origins/glow remain from v10.\n\nTEST 3 ABILITIES - ALL 0 AP\naqua   : main ground finisher411, neutral aerial dodge504; original main air combo\naqua 1 : ground 516 518 519 ; air 607 608 609\naqua 2 : ground 610 611 612 ; air 616 618 619\naqua 3 : ground 613 602 603 ; air 604 605 606\naqua 4 : ground 617 405 406 ; air 407 452 621\n\nThe first clip is attack one, second clip attack two, third clip the finisher.\nKH1's alternate second ground attack uses the same selected second clip.\nNumbered entries share the main movement/casting/reaction/Guard/Cartwheel poses;\nonly their combo assignments differ. Select one Aqua entry while idle. The\nother Aqua entries turn off automatically; native ability states stay intact.\nIds117..121 and saved selections remain compatible with v10.\n\nAERIAL DODGE TEST BEHAVIOR\nThis adds an animation action on logical Jump/Circle with a neutral left stick.\nA fresh press after releasing the takeoff button is required. Directional\nCircle, holding the initial jump, ground actions, attacks/casts/reactions,\nledge transitions, scenes and shortcut inputs do not start it.\n504 is fitted to the existing 40-frame fall record. The native motion clock\nstarts at zero; the pose plays once, then the normal 506 body is restored.\nLanding, attack/cast interruption, unequipping and actor/bank changes end it.\nThe native control step runs with only its Jump bits temporarily consumed\nduring the dodge; those input bits are restored immediately afterward.\nNormal directional movement, gravity, velocity and collisions remain native.\nThis test does NOT add BBS dodge travel, a vertical boost or invincibility.\nIf you hold Circle after the pose ends, KH1 may then enter its normal Glide.\n\nINSTALL\n1. Fully close KH1.\n2. Disable Aqua v10 and all older Aqua packages, Sora Restore Check and\n   Nine Styles / Dual Wield. Keep other Sora model/moveset replacements off.\n3. Import this ZIP into OpenKH and enable Aqua Animation Test v11.\n4. Build and Run, then load your save.\n5. Equip aqua or one of aqua 1..4 while idle. Missing entries are granted off;\n   saved selections are respected. Native entries are never evicted to fit.\n\nTEST ORDER\n- Equip aqua. Test its three-hit ground combo and the new 411 finisher.\n- Jump, release Circle, leave the left stick neutral, then tap Circle again.\n  Look for 504 once, followed by 506. Land and repeat. Also test directional\n  Circle and a held takeoff press; these should retain their native behavior.\n- Test interruption by attacking/casting and landing. Check normal Glide too.\n- Equip aqua 1, 2, 3 and 4 while idle; test each three-hit ground/air combo.\n  Unequip Slapshot, Sliding Dash, Vortex, Hurricane Blast and other native\n  combo replacements for a clean test. Guard and Dodge Roll still need their\n  native abilities; the new aerial pose needs no additional native ability.\n- Recheck Fire/Thunder/Cure and LEFT-hand effects. Turn all Aqua entries off\n  and check Sora's native poses/controls. Repeat on both saves, after room\n  transitions and after save reloads.\n\nRETURN\nReturn the NEW kh1-aqua.log beside the game EXE and a short video. Its first\nline must say ANIMATION TEST v11 Test 3. AIR DODGE READY confirms control-hook\nadmission; AIR DODGE 504 confirms the input trigger. AIR DODGE UNAVAILABLE\nleaves other Aqua poses available and retains native air input.\nProfile log values: 0 native, 1 aqua, 2 aqua 1, 3 aqua 2, 4 aqua 3, 5 aqua 4.\nCHECK_AQUA_V11.cmd optionally checks installation hashes and writes\nAqua_Animation_Check_v11.txt.\n\nSCOPE / RETAINED FEATURES\nBoth installed MSETs are original. Runtime body poses fit their existing\nheaders, table sizes, bone counts and eleven helpers. The aerial pose is a\nsecond body variant for the existing fall record, not an added native record.\nUnknown/foreign motion tables block writes. Hair rest rotations and anatomical\nwrist/forearm alignment corrections are retained. Only the supplied normal\nSora and Olympus banks are admitted. Native damage, hit events, spell scripts,\nMP, targeting, Guard coverage, Dodge Roll invincibility and actor travel remain.\nBBS command logic, effects, damage and hitboxes are not imported with a clip.\n\nSHARED CASTING FROM V10\nThunder and Cure normally share a native physical cast record. The existing\nactor-local request copy routes Thunder to a separate casting family. Blizzard\nand Gravity inherit317/390; Stop and Aero inherit318/427. Thunder uses 86 ground\nand 78 air frames instead of 68/68. This inherited timing still needs in-game\nverification. Fire's release/recovery follows continuous portions of316/391.\nUnequipping Aqua restores the exact original request lookup and mapped poses.\n\nFILE GUIDE\nABILITY_SETS.txt gives the exact Test 3 sequences.\nANIMATION_MAP.csv lists all five profiles' usual motion assignments.\nAIR_DODGE_MAPPING.csv describes the temporary 504 overlay for each profile.\nTEST_CLIP_SOURCES.csv gives new source banks, frame counts and payload hashes.\n411 uses the dedicated p02ex_313.arc variant; 504 uses p02ex_157.arc. Numeric\nlabels are not assumed to be official BBS command names.\nThe unchanged 349-clip source inventory remains under inventory. Use this\npackage's mapping CSVs for current ability assignments.\n\nOPTIONAL FALLBACKS\nTo disable only the new airborne input action, copy\nDISABLE_AIR_DODGE_kh1-aqua.ini beside the EXE as kh1-aqua.ini and restart.\nThe411 finisher, Test 3 combos, normal506 fall and left-hand magic remain.\nTo retain native weapon-tip spell attachments, use\nDISABLE_HAND_MAGIC_kh1-aqua.ini instead. You can combine air_dodge=0 and\nhand_magic=0 in one [aqua] INI. Remove the INI and restart to restore defaults.\n\nREMOVE ALL AQUA ENTRIES\nCopy REMOVE_AQUA_kh1-aqua.ini beside the game EXE as kh1-aqua.ini. Leave v11\ninstalled, restart and load each save to clean. Check AQUA ABILITIES REMOVED,\nthen save in-game. Exit, remove the INI, disable v11 and rebuild. Only ids117..121\nare removed; native ability order is preserved.\n\nVALIDATION\n49 tests execute the emitted PE DLL in a Win64 ABI mock host, including the\nreal control-entry detour and relocated-cookie trampoline, neutral/held/\ndirectional inputs, one use per airtime, native queueing, interruptions,\nlookup/body/input restoration, all five profiles/both banks, foreign-data and\nallocation/admission failures. 13 geometry/assignment checks cover all76 pose\nvariants, exact Test 3 IDs, original capacities, bind lengths/scales, hair,\nwrist helpers, native travel and retained jump/Fire transitions.\nClip616 fills the first air attack's available key pool; its fitted maximum\nposition error remains below the existing5-unit limit. No capacity expansion\nor relaxed fit limit is used.\nThese checks do not run Windows/KH1 or render Sora's mesh. The new control\nhook and aerial pose timing need an in-game test; clipping or pose transitions\nmay still need adjustment.\n"

SOURCE="AQUA V11 TEST 3 SOURCE\n\nNormal installation requires OpenKH/Panacea; these are development files.\n\nDLL BUILD / EXECUTION CHECK (Linux x64)\n  python3 generate_data.py\n  python3 build.py\n  python3 test_runtime.py\n  python3 test_visuals.py\nGCC, GNU ld with i386pep support and Python are needed. Geometry checks also\nneed NumPy/SciPy. Runtime tests map the final PE and execute its real exports\nand attachment detours against Win64 ABI mocks, not Windows or KH1.\n\nREBUILD POSES (optional; NumPy, SciPy, Pillow)\nFrom this source directory:\n  python3 retargeting/tools/build_aqua_complete_v11.py --profile 0 --output .\n  python3 retargeting/tools/build_aqua_complete_v11.py --profile 1 --output sets/p1\n  python3 retargeting/tools/build_aqua_complete_v11.py --profile 2 --output sets/p2\n  python3 retargeting/tools/build_aqua_complete_v11.py --profile 3 --output sets/p3\n  python3 retargeting/tools/build_aqua_complete_v11.py --profile 4 --output sets/p4\n  python3 retargeting/tools/build_aqua_complete_v11.py --profile 5 --output dodge\n  python3 generate_data.py\n  python3 build.py\n  python3 test_runtime.py\n  python3 test_visuals.py\n--slots followed by normal slot numbers rebuilds only those records in a\nprofile. Required source ARC files are in retargeting/core_source. Original\nMSET files are ../assets. Immutable baseline sampling caches are reproducible\nand are not distributed. V9 anatomical refinements are retained and applied once to each baseline.\n\nANATOMICAL WRIST PIVOTS\naqua_refine_v9.py keeps Sora's distal forearm helper angles at bind and applies\nthe hand's authored orientation at pivots100/205. Arm solves rotate the whole\ndistal forearm together and preserve the hand's orientation at that pivot.\nArm clearance includes interior arm samples. The new main ground finisher411\nuses the normal correction envelope; the old304 finisher is no longer selected. All local anatomical\noffsets/scales retain their bind values. The V8 reference contains 41 samples\nof ten joints per original converted motion; it supports an independent\nbounded-displacement checks for unchanged source actions only. New casts,\nfalling and the changed411 finisher are excluded from that historical comparison. It is not mesh\ncollision detection. Hair155..193 retains the v8 bind-rest correction.\n\nFIVE PROFILE GATE\nThe generated header stores original tables and five immutable after sets.\nUnchanged profile blocks are shared. All 47/46 records are admitted against\nthe known original/base/test sets before any writes. Selection changes wait\nfor idle. Ability ids117..121 are 0 AP. Newly enabled Aqua entries win and\nonly other Aqua entries are turned off. Missing entries are granted only if\nall fit with a terminator in the original 48-byte list. Native entries are\nnot evicted. Uninstall removes only ids117..121.\n\nNEUTRAL AERIAL DODGE\nThe main plan remains47 normal /46 Olympus records. Profile5 of the retargeting\nbuilder is a single non-looped504 variant of the existing fall record10.\ngenerate_data.py stores this as AquaPart.dodge; admission accepts it and the\nfast cache recognizes it only while the transient action is active.\naqua_air_dodge.h hooks Steam control0x2A6220 after exact17-byte admission. Its\ntrampoline copies the first10 bytes and rewrites the RIP-relative security-\ncookie load as mov rax, imm64; mov rax,[rax], targeting original0x554A88.\nThe original control, can-act0x297870 and queued-motion0x29F980 bytes are\nverified before installation. The last two functions are called, not hooked.\nFresh merged logical Jump/Circle bits6, neutral tilt<=.15, free air1/2,\nheight>1, an admitted body bank and no busy/native queued action authorize504.\nOne use per airtime, armed after button release. Beginning from fall6 resets\nonly actor+16C to zero; beginning from rise queues native fall6. Native state,\nvelocity/gravity, collision and defense flags stay untouched. The control\ncall temporarily masks only Jump bits at pad+4/+8/+10/+14, then restores those\nbits without undoing native changes to other buttons. Clock39, looping,\nlanding or interruption restores the normal506 pose. Unknown/unloaded records\nare never restored by writing stale pointers. The action adds no invulnerability.\nThe native clock remains authoritative; waiting for a queued fall is bounded.\nair_dodge_validation.json records original executable evidence. The test host\nexecutes the real detour/trampoline and native can-act bytes; native queue and\ncontrol bodies are mocked. Actual Windows/KH1 testing remains outstanding.\n\nACTION CAST LOOKUP\nNative Steam command handlers dispatch ground magic with 0x36+spell and air\nmagic with 0x83+spell. Thunder is index2, Cure index3. The supplied MSETs share\ntheir physical record. aqua_cast_requests.h changes actor+1D8 to an immutable\n1408-byte request copy while a verified Aqua profile is active. Only Thunder\nmoves to the alternate casting family (normal55/80, Olympus18/42); all other\nrequest words and native flags remain. The original table is never written.\nNative resolver0x2A01E0 reads that field (+8 from actor+1D0). All body and\nrequest destinations must pass admission before writes; idle-only switching,\nper-bank original pointers, foreign-pointer rejection and exact restoration\nare tested. cast_request_validation.json records native instruction evidence\nfrom the supplied executable. No new entry-point detour is used here.\nThunder therefore uses 86 ground / 78 air frames, instead of the shared\n68/68 frames. Native per-record event tracks stay intact. Final spell timing\nhas not been tested in KH1. Blizzard/Gravity inherit317/390; Stop/Aero318/427.\n\nLEFT-HAND MAGIC\nThe two native entry points and admitted instruction spans are unchanged from\nv8. Their direct matrix selector is now0x20CE, the LEFT palm206, in all five\nprofiles. Native cast requests, current actor/bank, event/script exclusions\nand native fallthrough are retained. No spell-resource or projectile script\nis replaced. The supplied executable is not included; its original hash and\nthe entry spans are in native_attachment_validation.json.\n\nCAPACITY / SOURCE IDS\nNo motion/header/table expansion is used. The cast lookup copy has the original\n352 request words; only Thunder entries0x38/0x85 change their physical slot. The original eleven helpers and\nnative travel remain. Four sets change seven physical combo records each:\nC8 first, C9/CA second, CB finisher, CC first air, CD second air, CE finisher.\nThe donor selection is in aqua_v11_plan.py. Numeric IDs retain their exact\nsource bank/hash in TEST_CLIP_SOURCES.csv; no command names are inferred.\nThe source inventory files under ../inventory retain v8's source metadata.\nCurrent ability mappings are ../ANIMATION_MAP.csv.\n\nExisting upstream licenses and notices are retained in licenses.\nFormat reference: https://openkh.dev/bbs/file/type/pam.html\n"

def build():
    d=ROOT/'ability_v11';runtime=json.loads((d/'runtime_validation.json').read_text());geometry=json.loads((d/'visual_validation.json').read_text())
    reports=[json.loads((d/'curve_validation.json').read_text())]+[json.loads((d/f'sets/p{i}/curve_validation.json').read_text()) for i in range(1,5)]
    dodge=json.loads((d/'dodge/curve_validation.json').read_text())
    assert runtime['passed'] and geometry['passed'] and all(r['passed'] for r in reports+[dodge])
    shutil.copytree(ROOT/'KH1FM_Aqua_Animation_Test_v10',DEST,dirs_exist_ok=True)
    for name in ['CHECK_AQUA_V10.cmd','Check_Aqua_Animations_v10.ps1','source/arm_alignment_validation.json']:(DEST/name).unlink(missing_ok=True)
    for n in ['aqua.c','aqua_magic.h','aqua_cast_requests.h','aqua_air_dodge.h','aqua_data.h','build.py','generate_data.py','test_runtime.py','test_bridge.c','test_visuals.py',
              'curve_validation.json','data_validation.json','runtime_validation.json','visual_validation.json','cast_request_validation.json','air_dodge_validation.json']:
        shutil.copy2(d/n,DEST/'source'/n)
    for name in ['fixtures','sets','dodge']:shutil.copytree(d/name,DEST/'source'/name,dirs_exist_ok=True)
    shutil.copy2(d/'kh1-aqua.dll',DEST/'dll/kh1-aqua.dll')
    for n in ['build_aqua_complete_v11.py','aqua_v11_plan.py','package_aqua_v11.py']:shutil.copy2(ROOT/'tools'/n,DEST/'source/retargeting/tools'/n)
    for n in sorted(set(BANK.values())):
        name=f'p02ex_{n}.arc';shutil.copy2(ROOT/'capture_20261101/Sources/data/bbs/arc/pc'/name,DEST/'source/retargeting/core_source'/name)
    (DEST/'README_FIRST.txt').write_text(README);(DEST/'source/README_SOURCE.txt').write_text(SOURCE)
    manifest=(ROOT/'KH1FM_Aqua_Animation_Test_v10/mod.yml').read_text();a=manifest.index('description:');b=manifest.index('assets:')
    desc='Test 3: main aqua ground finisher411 and fresh neutral-air Jump/Circle dodge504; aqua 1..4 use four new ground/air combos. Retains fall506, action casts, LEFT-hand magic and wrist/hair corrections. Steam Global / Panacea; disable older Aqua packages and Nine Styles / Dual Wield.'
    manifest=manifest[:a]+'description: >-\n  '+desc+'\n'+manifest[b:]
    (DEST/'mod.yml').write_text(manifest.replace('Animation Test v10','Animation Test v11'))
    checker=(ROOT/'KH1FM_Aqua_Animation_Test_v10/Check_Aqua_Animations_v10.ps1').read_text().replace('v10','v11').replace('CHECK_AQUA_V10','CHECK_AQUA_V11')
    (DEST/'Check_Aqua_Animations_v11.ps1').write_text(checker)
    (DEST/'CHECK_AQUA_V11.cmd').write_bytes(b'@echo off\r\nsetlocal\r\npowershell.exe -NoLogo -NoProfile -ExecutionPolicy Bypass -File "%~dp0Check_Aqua_Animations_v11.ps1" %*\r\npause\r\n')
    (DEST/'REMOVE_AQUA_kh1-aqua.ini').write_text('[aqua]\nremove_aqua=1\nhand_magic=0\nair_dodge=0\n')
    (DEST/'DISABLE_HAND_MAGIC_kh1-aqua.ini').write_text('[aqua]\nremove_aqua=0\nhand_magic=0\nair_dodge=1\n')
    (DEST/'DISABLE_AIR_DODGE_kh1-aqua.ini').write_text('[aqua]\nremove_aqua=0\nhand_magic=1\nair_dodge=0\n')
    labels=['aqua']+[f'aqua {i}' for i in range(1,5)]
    (DEST/'ABILITY_SETS.txt').write_text('\n'.join([f'Ability {label} / id{117+i} / 0 AP' + (' / main finisher411; air dodge504' if not i else f' / ground {" ".join(SETS[i-1][0])} / air {" ".join(SETS[i-1][1])}') for i,label in enumerate(labels)])+'\n\nSelect one while idle. Neutral-air504 is shared by all five.\n')
    maps=[];sources=[];airmaps=[]
    sys.path.insert(0,str(ROOT/'tools'));from bbs_source_inspector import read_arc,read_pam
    for profile in range(5):
        active={r['normal_slot']:r for r in reports[0]['motions']}
        if profile:active.update({r['normal_slot']:r for r in reports[profile]['motions']})
        for r in sorted(active.values(),key=lambda r:r['normal_slot']):
            maps.append({'Ability':labels[profile],'Ability id':117+profile,'Action':r['action'],'Native request':f'0x{r["request"]:02X}',
              'Normal slot':r['normal_slot'],'Olympus slot':r['olympus_slot'] if r['olympus_slot']!=0xffffffff else 'not present',
              'Aqua clip':r['donor'],'Source bank':r['source_bank'],'Source frame range':str(r['source_range']) if r['source_range'] else 'full',
              'Pose loop':r['loop'],'Native frames':r['native_frames'],'Root policy':r['root']})
        airmaps.append({'Ability':labels[profile],'Ability id':117+profile,'Action':'Neutral aerial dodge','Aqua clip':'504',
            'Trigger':'Fresh airborne Jump/Circle after release; neutral left stick; once per airtime','Normal slot':10,'Olympus slot':10,
            'Native frames':40,'Normal falling clip':'506','Input restored after control':True,'Native gravity and velocity':True})
    for profile,report in enumerate(reports+[dodge]):
        for r in report['motions']:
            if not profile and r['normal_slot']!=101:continue
            arc=ROOT/'capture_20261101/Sources/data/bbs/arc/pc'/r['source_bank'];members,_=read_arc(arc.read_bytes())
            found=[]
            for member,data in members:
                if not data.startswith(b'PAM\0'):continue
                for a in read_pam(data,54):
                    if a.name!=r['donor']:continue
                    start=struct.unpack_from('<I',data,16+16*a.slot)[0]
                    found.append({'Ability':labels[profile] if profile<5 else 'all Aqua entries','Action':r['action'],'Normal slot':r['normal_slot'],
                        'Source name':a.name,'Source bank':r['source_bank'],'PAM member':member,'Source frames':a.frame_count,'Source FPS':a.fps,
                        'Source frame range':str(r['source_range']) if r['source_range'] else 'full','Animation SHA256':hashlib.sha256(data[start:a.data_end]).hexdigest(),
                        'Native frames':r['native_frames'],'Native FPS':60})
            assert len(found)==1,(r['donor'],r['source_bank'],len(found));sources+=found
    for name,rows in [('ANIMATION_MAP.csv',maps),('AIR_DODGE_MAPPING.csv',airmaps),('TEST_CLIP_SOURCES.csv',sources)]:
        with (DEST/name).open('w',newline='',encoding='utf-8-sig') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
    expected={'version':11,'assets':[]}
    for name,actual in [('dll/kh1-aqua.dll',DEST/'dll/kh1-aqua.dll'),('xa_ex_0010.mset',DEST/'assets/xa_ex_0010.mset'),('xa_ex_0010_he.mset',DEST/'assets/xa_ex_0010_he.mset')]:
        expected['assets'].append({'name':name,'sha256':sha(actual),'bytes':actual.stat().st_size})
    (DEST/'expected_assets.json').write_text(json.dumps(expected,indent=2)+'\n')
    records=[r for report in reports+[dodge] for r in report['motions']]
    validation={'version':11,'test_round':3,'offline_checks_passed':True,'game_runtime_tested':False,
        'abilities':labels,'ability_ids':list(range(117,122)),'main_ground_finisher':'411','neutral_air_dodge':'504','normal_falling':'506',
        'test_3_combos':SETS,'normal_motion_records_per_profile':47,'olympus_motion_records_per_profile':46,
        'unique_generated_pose_variants':len(records),'actual_pe_mock_tests':runtime['tests'],'geometry_assignment_tests':geometry['tests'],
        'pose_samples':sum(r['validated_pose_samples'] for r in records),'max_pose_position_fit_error':max(r['max_pose_position_error'] for r in records),
        'max_non_root_attachment_translation_error':max(r['max_non_root_attachment_translation_error'] for r in records),
        'max_scale_error':max(r['max_scale_error'] for r in records),'native_travel_error':max(r['root_helper_error'] for r in records),
        'original_motion_lengths_headers_counts_and_msets_preserved':True,'helper_slots':11,'left_palm_magic':206,
        'air_dodge_one_per_airtime':True,'air_dodge_extra_invulnerability':False,'dll_sha256':sha(DEST/'dll/kh1-aqua.dll'),
        'limitations':['Windows/KH1 execution and rendered appearance pending','New input detour and airborne transition require in-game testing',
            '504 uses native fall gravity and40-frame timing; no added BBS travel or invulnerability','Thunder retains v10 alternate casting duration86/78']}
    (DEST/'validation.json').write_text(json.dumps(validation,indent=2)+'\n')
    with zipfile.ZipFile(DEST.with_suffix('.zip'),'w',zipfile.ZIP_DEFLATED,compresslevel=9) as z:
        for p in sorted(DEST.rglob('*')):
            if p.is_file() and '__pycache__' not in p.parts:z.write(p,p.relative_to(DEST))
    print(json.dumps({'zip':str(DEST.with_suffix('.zip')),'bytes':DEST.with_suffix('.zip').stat().st_size,'sha256':sha(DEST.with_suffix('.zip')),'validation':validation},indent=2))
if __name__=='__main__':build()
